 1	//! Integration test for the entity seacrh endpoint.
 2	//! This test suite expects a pre-loaded database.
 3	//!
 4	//!
 5	
 6	use std::{collections::HashMap, ffi::OsString, time::Duration};
 7	
 8	use clap::Parser;
 9	use exposed::{
10	    domain::{
11	        models::{entity_ingestion::IngestionKey, entity_search::EntitySearchRequest},
12	        repositories::parliament_member_repository::ParliamentMemberRepo,
13	    },
14	    inbound::cli::{DataArgs, run_cli},
15	    outbound::ExposedDatabase,
16	};
17	use sqlx::{ConnectOptions, PgPool};
18	use tempfile::TempDir;
19	use tokio::time;
20	
21	use crate::common::{cli_fetcher_config, cli_loader_config, search_entities, start_app};
22	
23	mod common;
24	
25	#[tokio::test]
26	async fn shows_no_hsbc_duplicates() {
27	    let _guard = start_app().await.unwrap();
28	    time::sleep(Duration::from_secs(2)).await;
29	
30	    let known_duplicate = EntitySearchRequest::new_with_strictness("HSBC".into(), 10, 0.9).unwrap();
31	    let entities = search_entities(&known_duplicate).await.unwrap();
32	
33	    let mut duplicates: HashMap<String, usize> = HashMap::new();
34	    for e in entities.into_iter() {
35	        duplicates
36	            .entry(e.get("name").unwrap().as_str().unwrap().into())
37	            .and_modify(|count| *count += 1)
38	            .or_insert(1);
39	    }
40	
41	    assert_eq!(duplicates.get("HSBC UK Bank plc"), Some(&1));
42	    assert_eq!(duplicates.get("HSBC UK Bank PLC"), Some(&1));
43	    assert_eq!(duplicates.get("HSBC UK (Ian Stuart, CEO)"), Some(&1));
44	}
45	
46	#[sqlx::test(migrations = "../db/migrations")]
47	async fn parliament_api_parses_all_sitting_members(pool: PgPool) -> sqlx::Result<()> {
48	    let ingestion_key = IngestionKey::default();
49	    let tmp = TempDir::new().unwrap();
50	
51	    let (_file, path) = cli_fetcher_config(&tmp);
52	    let args = DataArgs::try_parse_from([
53	        OsString::from("exposed-data"),
54	        "members".into(),
55	        "fetch".into(),
56	        path.into_os_string(),
57	        "--ingestion-key".into(),
58	        ingestion_key.to_string().into(),
59	    ])
60	    .unwrap();
61	    run_cli(args).await.unwrap();
62	
63	    let url = pool.connect_options().to_url_lossy();
64	    let (_file, path) = cli_loader_config(&tmp, url.to_string().as_str());
65	    let args = DataArgs::try_parse_from([
66	        OsString::from("exposed-data"),
67	        "members".into(),
68	        "load".into(),
69	        path.into_os_string(),
70	        "--ingestion-key".into(),
71	        ingestion_key.to_string().into(),
72	    ])
73	    .unwrap();
74	    run_cli(args).await.unwrap();
75	
76	    let db = ExposedDatabase::from(pool);
77	
78	    let params =
79	        EntitySearchRequest::new_with_strictness("John McDonnell".into(), 10, 0.8).unwrap();
80	    let res = db.get_members_by_text_search_score(&params).await.unwrap();
81	
82	    let (mp, _) = res.first().unwrap();
83	    assert_eq!(mp.name(), "John McDonnell".to_string());
84	
85	    Ok(())
86	}

